mapper.update:
update verification_record
set result = #{result},
    failure_reason = #{failureReason}
where id = #{id}

mapper.select:
select vr.id, vr.request_no, vr.verified_at,
       t.ticket_code, item.visitor_name, item.ticket_type_name,
       vr.verifier_id, vr.verifier_name_snapshot as verifier_name,
       vr.result, vr.failure_reason, vr.device_no
from verification_record vr
join ticket t on t.id = vr.ticket_id
join booking_order_item item on item.id = t.order_item_id
join booking_order bo on bo.id = item.order_id
where bo.venue_id = #{venueId}

    and t.ticket_code = #{query.ticketCode}


    and vr.result = #{query.result}


    and cast(vr.verified_at as date) = #{query.verificationDate}

order by vr.verified_at desc, vr.id desc
